    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  },
  {
    "statement": "TM-score between two identical structures is 1, independent of protein length.",
    "motivation": "This explores a direct corollary of O4: when comparing a structure to itself, all distances d_i=0, so each term in the sum equals 1, giving TM-score = (1/L)*L = 1. This is a checkable mathematical consequence of the definition.",
    "depends_on": [
      "O4"
    ],
    "factor_sequence": [
      "O4"
    ]
  },
  {
    "statement": "If two proteins have identical native structures, their free energy minima (per O1) have the same conformational coordinates up to rigid-body transformation.",
    "motivation": "This clarifies what 'identical native structures' means operationally in the context of O1. It makes explicit the geometric interpretation needed to connect O1 with structural comparison metrics like TM-score.",
    "depends_on": [
      "O1"
    ],
    "factor_sequence": [
      "O1"
    ]
  },
  {
    "statement": "For two proteins with identical native structures AND identical lengths, their TM-scores to any third reference structure are equal.",
